import React, {useContext, useState} from 'react';
import {Context} from "../index";
import {useHistory} from 'react-router-dom';
import Card from 'react-bootstrap/esm/Col';
import {removeDish} from "../http/dishAPI";
import Button from 'react-bootstrap/Button';
import {SHOP_ROUTE} from '../utils/consts';
import { observer } from 'mobx-react-lite';
import { useParams } from 'react-router-dom/cjs/react-router-dom';
import AcceptChoice from './modals/AcceptChoice'

const RemoveDish = () => {
    const [acceptVisible, setAcceptVisible] = useState(false)

    const {dish} = useContext(Context)
    const {id} = useParams()
    const history = useHistory()

    const delDish = (id) => {
        removeDish(id)
        history.push(SHOP_ROUTE)
    }

    return (
            <Card>
            <Button 
                variant='outline-danger'
                className='mt-3'
                onClick={() => setAcceptVisible(true)}
            >
                Видалити товар
            </Button>

            <AcceptChoice onClick={() => {AcceptChoice? delDish:[]}} show={acceptVisible} onHide={() => setAcceptVisible(false)}/>
        </Card>
    );
};

export default RemoveDish;
